from pathlib import Path
import json, csv, re, collections

HERE=Path(__file__).resolve().parent
talks=[]; items=[]; problems=[]; corrections=[]; sources=[]; bibliography=[]

def talk(record,date,speaker,pages,title,summary,kind='talk'):
    talks.append(dict(record=record,date=date,speaker=speaker,pages=pages,title=title,kind=kind,summary=summary))

def item(record,pages,kind,title,notes,statement,fate,refs=(),cls='E',reconstruction='',status='Established with the hypotheses in the statement.',literal='correct with missing hypotheses',match='exact',verification='read the result',development='none',problem='',worth='',confidence='high',speaker=None):
    n=1+sum(x['record']==record for x in items)
    x=dict(id=f'1970-{record}.{n}',record=record,pages=pages,kind=kind,title=title,notes=notes,statement=statement,reconstruction=reconstruction,**{'class':cls},fate=fate,present_status='As of 9 November 2026: '+status,literal_correctness=literal,publication_match=match,verification=verification,development=development,problem=problem,worth=worth,refs=list(refs),confidence=confidence)
    if speaker:x['speaker']=speaker
    items.append(x)
    return x['id']

def problem(pid,title,statement,occurrences,status,refs):
    problems.append(dict(id=pid,title=title,statement=statement,occurrences=occurrences,status=status,status_date='2026-11',refs=refs))

def corr(page,place,reads,should,evidence,applies='both',typ='faithful_error'):
    corrections.append(dict(page=page,place=place,transcription_reads=reads,should_read=should,evidence=evidence,applies_to=applies,type=typ))

def bib(key,kind,fields,url,evidence):
    fields={**fields,'url':url,'note':'verified','annote':evidence}
    bibliography.append('@'+kind+'{'+key+',\n'+',\n'.join('  '+k+' = {'+str(v)+'}' for k,v in fields.items())+'\n}\n')
    sources.append(dict(key=key,url=url,accessed='2026-11-09',evidence=evidence))

def save():
    for name,data in [('talks',talks),('items',items),('problems',problems),('sources',sources)]:
        (HERE/(name+'.json')).write_text(json.dumps(data,ensure_ascii=False,indent=2)+'\n')
    with (HERE/'corrections.csv').open('w',newline='') as f:
        w=csv.DictWriter(f,fieldnames=['page','place','transcription_reads','should_read','evidence','applies_to','type']);w.writeheader();w.writerows(corrections)
    (HERE/'references.bib').write_text('\n'.join(bibliography))
    print('Checkpoint:',len(talks),'records;',len(items),'items;',len(problems),'problems;',len(corrections),'corrections;',dict(collections.Counter(x['class'] for x in items)))

