bib('bott1976characteristic','article',dict(author='Bott, Raoul',title='On characteristic classes in the framework of Gelfand--Fuks cohomology',journal='Astérisque',volume='32--33',pages='113--139',year=1976),'https://www.numdam.org/article/AST_1976__32-33__113_0.pdf','Full author article opened. Section 2, pp. 125--126, gives the degree-truncated characteristic algebra; section 4, pp. 135--136, identifies its characteristic classes with those of the normal bundle TM/E and explicitly deduces the earlier vanishing obstruction.')
